11:     if (!drop?.item) return;
12:     this.bag.push(drop.item);
13:     this.g.world.drops = this.g.world.drops.filter(d => d !== drop);
14:     this.g.ui?.lootToast(drop.item);
15:     this.g.ui?.renderPanel();
