18:     const index = this.bag.findIndex(item => item.id === itemId);
19:     if (index < 0) return;
20:     const item = this.bag[index];
21:     const slot = item.slot || 'Main hand';
22:     const old = this.equipment[slot];
23:     this.equipment[slot] = item;
24:     this.bag.splice(index, 1);
25:     if (old) this.bag.push(old);
26:     this.recalculate();
27:     this.g.ui.toast(`${item.name} equipped.`);
28:     this.g.ui.renderPanel();
29:   }
30:   unequip(slot) {
31:     if (!this.equipment[slot]) return;
32:     this.bag.push(this.equipment[slot]);
33:     delete this.equipment[slot];
34:     this.recalculate();
35:     this.g.ui.renderPanel();
36:   }
