42:     const weapon = equipped.filter(item => item.type === 'weapon').reduce((sum, item) => sum + (item.power || 0), 0);
43:     p.damage = (p.baseDamage || 16) + weapon * .55;
44:     p.maxHp = (p.baseMaxHp || 120) + equipped.filter(item => item.type === 'armor').reduce((sum, item) => sum + (item.power || 0) * 2, 0);
45:     p.armor = Math.min(45, (p.baseArmor || 0) + equipped.filter(item => item.type === 'armor').reduce((sum, item) => sum + (item.power || 0) * .55, 0));
